(() => {
  const LOGO = "data:image/png;base64,";
  const ISLAND = "flavox-dynamic-island";
  const PROCESS = "flavox-upload-processing";
  let islandTimer, processTimer;

  const txt = el => (el?.textContent || "").replace(/\s+/g," ").trim().toLowerCase();

  function isUploadArea(el) {
    if (!el || el.id === PROCESS) return false;
    const t = txt(el);
    return t.includes("select video to upload") || t.includes("select video") || t.includes("drag and drop it here");
  }

  function findInput() {
    return [...document.querySelectorAll('input[type="file"]')]
      .find(i => /video/i.test(i.accept || "")) || document.querySelector('input[type="file"]');
  }

  function findArea(input) {
    let n = input;
    for (let i=0;i<9 && n;i++,n=n.parentElement) {
      if (isUploadArea(n)) return n;
    }
    return [...document.querySelectorAll("div,section,main")]
      .find(n => isUploadArea(n) && n.getBoundingClientRect().width > 250 && n.getBoundingClientRect().height > 120) || null;
  }

  function showIsland() {
    let el=document.getElementById(ISLAND);
    if(!el){
      el=document.createElement("div");
      el.id=ISLAND;
      el.innerHTML=`<div class="flavox-logo-wrap"><img class="flavox-logo" src="${LOGO}"></div>
      <div class="flavox-copy"><div class="flavox-name">FLAVOX UPLOADER</div></div>
      <button class="flavox-close">×</button>`;
      document.documentElement.appendChild(el);
      el.querySelector(".flavox-close").onclick=()=>el.classList.remove("flavox-show");
    }
    el.classList.add("flavox-show");
    clearTimeout(islandTimer);
    islandTimer=setTimeout(()=>el.classList.remove("flavox-show"),5000);
  }

  function ensureStyle(){
    if(document.getElementById("flavox-processing-style")) return;
    const s=document.createElement("style");
    s.id="flavox-processing-style";
    s.textContent=`#${PROCESS}{position:absolute!important;inset:0!important;z-index:999999!important;display:flex!important;align-items:center!important;justify-content:center!important;background:radial-gradient(circle at 50% 0,#211805 0,#05080b 58%,#030405 100%)!important;border-radius:12px!important;color:#fff!important;font-family:Inter,system-ui,Arial,sans-serif!important}
    #${PROCESS} .fx-inner{width:min(600px,92%);text-align:center;padding:25px 20px}
    #${PROCESS} .fx-icon{width:58px;height:58px;border-radius:50%;object-fit:cover;border:1px solid #c8952c;box-shadow:0 0 25px rgba(238,177,48,.3);display:block;margin:auto auto 11px}
    #${PROCESS} .fx-title{font-size:18px;font-weight:900;color:#f5f0e7}
    #${PROCESS} .fx-sub{font-size:11px;color:#89857d;margin-top:5px}
    #${PROCESS} .fx-size{font-size:10px;color:#c5b17f;margin-top:8px}
    #${PROCESS} .fx-track{height:9px;background:#17191b;border:1px solid #40341e;border-radius:10px;margin:17px auto 8px;overflow:hidden;width:min(430px,90%)}
    #${PROCESS} .fx-bar{height:100%;width:0;background:linear-gradient(90deg,#9b650b,#ffd86b,#b8780d);box-shadow:0 0 12px rgba(255,201,72,.6);transition:width .12s linear}
    #${PROCESS} .fx-line{display:flex;justify-content:space-between;width:min(430px,90%);margin:auto;color:#928a7b;font-size:10px}
    #${PROCESS} .fx-ready{margin-top:12px;color:#ffd15b;font-size:12px;font-weight:900}`;
    document.head.appendChild(s);
  }

  function bytes(n){
    if(n<1048576) return (n/1024).toFixed(1)+" KB";
    if(n<1073741824) return (n/1048576).toFixed(2)+" MB";
    return (n/1073741824).toFixed(2)+" GB";
  }

  function processVideo(input,file){
    const area=findArea(input);
    if(!area) return;
    ensureStyle();
    const old=document.getElementById(PROCESS);
    if(old) old.remove();
    area.style.position="relative";

    const root=document.createElement("div");
    root.id=PROCESS;
    root.innerHTML=`<div class="fx-inner">
      <img class="fx-icon" src="${LOGO}">
      <div class="fx-title">Rendering video…</div>
      <div class="fx-sub">FLAVOX is preparing your video for high-quality TikTok upload</div>
      <div class="fx-size">Source size: ${bytes(file.size)}</div>
      <div class="fx-track"><div class="fx-bar"></div></div>
      <div class="fx-line"><span class="fx-stage">Rendering</span><span class="fx-percent">0%</span></div>
    </div>`;
    area.appendChild(root);

    const bar=root.querySelector(".fx-bar"), stage=root.querySelector(".fx-stage"), pct=root.querySelector(".fx-percent");
    const title=root.querySelector(".fx-title"), sub=root.querySelector(".fx-sub");

    const v=document.createElement("video");
    v.preload="metadata";
    const u=URL.createObjectURL(file);
    v.onloadedmetadata=()=>{
      root.querySelector(".fx-size").textContent=`Source size: ${bytes(file.size)} • ${v.videoWidth}×${v.videoHeight} • ${v.duration.toFixed(1)}s`;
      URL.revokeObjectURL(u);
    };
    v.src=u;

    clearInterval(processTimer);
    const duration=Math.min(12000,Math.max(2500,2500+(file.size/1048576)*220));
    const start=performance.now();

    processTimer=setInterval(()=>{
      const p=Math.min(100,(performance.now()-start)/duration*100);
      bar.style.width=p+"%"; pct.textContent=Math.round(p)+"%";
      if(p<28){stage.textContent="Rendering";title.textContent="Rendering video…";}
      else if(p<58){stage.textContent="Analysing video";title.textContent="Analysing video…";}
      else if(p<82){stage.textContent="Checking quality";title.textContent="Checking quality…";}
      else if(p<100){stage.textContent="Preparing upload";title.textContent="Preparing upload…";}
      else{
        clearInterval(processTimer);
        stage.textContent="Complete"; pct.textContent="100%";
        title.textContent="Processing complete ✓";
        sub.textContent="Moving to the next TikTok Studio step…";
        root.querySelector(".fx-size").textContent += " • Ready";

        // Do not fake an upload or create a second page.
        // First remove FLAVOX's visual overlay, then use TikTok Studio's
        // own real Next/Continue button when it is available.
        setTimeout(() => {
          root.remove();
          clickTikTokNext();
        }, 700);
      }
    },80);
  }



  const FLAVOX_CREDIT = "•Uploder method by -@flavox.3dits";

  function addFlavoxDescriptionCredit() {
    const selectors = [
      'textarea',
      'input[placeholder*="Describe" i]',
      'textarea[placeholder*="Describe" i]',
      '[contenteditable="true"]'
    ];

    const fields = [...new Set(selectors.flatMap(s => {
      try { return [...document.querySelectorAll(s)]; } catch { return []; }
    }))];

    const field = fields.find(el => {
      const ph = (el.getAttribute("placeholder") || "").toLowerCase();
      const aria = (el.getAttribute("aria-label") || "").toLowerCase();
      return ph.includes("describe") || ph.includes("caption") ||
             aria.includes("describe") || aria.includes("caption") ||
             el.tagName === "TEXTAREA";
    });

    if (!field) return false;

    const current = field.isContentEditable
      ? (field.innerText || "")
      : (field.value || "");

    if (current.includes(FLAVOX_CREDIT)) return true;

    const next = current.trim()
      ? current.replace(/\s+$/, "") + "\n" + FLAVOX_CREDIT
      : FLAVOX_CREDIT;

    if (field.isContentEditable) {
      field.focus();
      field.textContent = next;
      field.dispatchEvent(new InputEvent("input", {
        bubbles: true,
        inputType: "insertText",
        data: FLAVOX_CREDIT
      }));
    } else {
      const setter = Object.getOwnPropertyDescriptor(
        HTMLTextAreaElement.prototype, "value"
      )?.set || Object.getOwnPropertyDescriptor(
        HTMLInputElement.prototype, "value"
      )?.set;

      if (setter) setter.call(field, next);
      else field.value = next;

      field.dispatchEvent(new Event("input", {bubbles:true}));
      field.dispatchEvent(new Event("change", {bubbles:true}));
    }
    return true;
  }

  function watchPublishDescription() {
    let tries = 0;
    const timer = setInterval(() => {
      tries++;
      if (addFlavoxDescriptionCredit() || tries >= 30) {
        clearInterval(timer);
      }
    }, 500);
  }

  function hookPublishButton() {
    const buttons = [...document.querySelectorAll("button,[role='button']")];
    buttons.forEach(btn => {
      if (btn.dataset.flavoxPublishHooked) return;
      const t = (btn.textContent || "").replace(/\s+/g," ").trim().toLowerCase();
      if (t === "post" || t === "publish") {
        btn.dataset.flavoxPublishHooked = "1";
        btn.addEventListener("click", () => {
          // Let TikTok open/validate its publishing form first, then add the credit.
          setTimeout(watchPublishDescription, 300);
        }, true);
      }
    });
  }

  function clickTikTokNext(){
    const candidates = [...document.querySelectorAll("button,[role='button'],div")]
      .filter(el => {
        if (!el || el.offsetParent === null) return false;
        const t = (el.textContent || "").replace(/\s+/g," ").trim().toLowerCase();
        return /^(next|continue|go next|next step)$/.test(t);
      })
      .sort((a,b) => {
        const ar=a.getBoundingClientRect(), br=b.getBoundingClientRect();
        return (br.width*br.height) - (ar.width*ar.height);
      });

    const next = candidates[0];
    if (next) {
      next.scrollIntoView({block:"center", behavior:"smooth"});
      setTimeout(() => next.click(), 250);
    }
  }


  function loadFlavoxCompression(){
    if(window.FLAVOX_COMPRESSION) return Promise.resolve();
    return new Promise((resolve,reject)=>{
      const s=document.createElement("script");
      s.src=chrome.runtime.getURL("compression.js");
      s.onload=resolve;
      s.onerror=reject;
      (document.head||document.documentElement).appendChild(s);
    });
  }
  loadFlavoxCompression().catch(()=>{});

  function hook(){
    const input=findInput();
    if(!input || input.dataset.flavoxHooked) return;
    input.dataset.flavoxHooked="1";
    input.addEventListener("change",()=>{
      const f=input.files?.[0];
      if(f && f.type.startsWith("video/")) processVideo(input,f);
    },true);
  }

  const isStudio=()=>location.hostname==="www.tiktok.com" &&
    (location.pathname.includes("/tiktokstudio") || location.pathname.includes("/upload"));

  if(isStudio()) setTimeout(showIsland,500);
  let last=location.href;
  setInterval(()=>{
    if(location.href!==last){
      last=location.href;
      if(isStudio()) setTimeout(showIsland,350);
    }
  },500);

  hook();
  new MutationObserver(hook).observe(document.documentElement,{subtree:true,childList:true});
  new MutationObserver(() => { hookPublishButton(); }).observe(document.documentElement,{subtree:true,childList:true});
  hookPublishButton();
  document.addEventListener("click",()=>setTimeout(hook,250),true);

  if(chrome?.runtime?.onMessage){
    chrome.runtime.onMessage.addListener(msg=>{
      if(msg?.type==="FLAVOX_SHOW_ISLAND") showIsland();
    });
  }
})();
